description:
Create a content rule. Config omitted → smart defaults.
config by condition_type:
- score_threshold: {"scoreType":"seo","operator":">=","threshold":70}
- word_count: {"operator":">=","min":300}
- meta_required: {"requireTitle":true,"requireDescription":true}
- verify_chips: {"maxAllowed":0}
- term_compliance: {"checkNever":true,"checkAvoid":true}
- link_count: {"linkType":"internal","operator":">=","min":2}
- section_required: {"headingPattern":"FAQ","isRegex":false} *
- regex_pattern: {"pattern":"\\bTODO\\b","flags":"gi","mustMatch":false} *
- competitor_filter: {"competitors":["Acme"]} * (*=config required)
